-- V26: Original educational TOEIC-style vocabulary; not an official ETS word list.
-- Stable identifiers, safe on both fresh and previously demo-seeded databases.
-- Existing personal decks and SRS data are deliberately untouched.

CREATE TEMP TABLE v26_seed_decks (deck_id uuid, name text, description text, category text) ON COMMIT DROP;

SELECT deck_id,name,description,category,'Original educational content',true FROM v26_seed_decks WHERE true
ON CONFLICT (deck_id) DO UPDATE SET name=EXCLUDED.name,description=EXCLUDED.description,category=EXCLUDED.category,is_published=true,updated_at=now();

CREATE TEMP TABLE v26_seed_words (deck_id uuid, vocabulary_id uuid, word text, meaning text, part_of_speech text, example text, display_order integer) ON COMMIT DROP;

-- Prefer the existing vocabulary ID for any manually seeded word already linked to this deck.
-- Avoid changing previously created vocabulary records or enrollment copies.
CREATE TEMP TABLE v26_resolved_words ON COMMIT DROP AS
SELECT s.*, COALESCE(existing.vocabulary_id, s.vocabulary_id) AS resolved_id
FROM v26_seed_words s
LEFT JOIN LATERAL (
  SELECT v.vocabulary_id FROM system_deck_vocabularies l
  JOIN system_vocabularies v ON v.vocabulary_id=l.vocabulary_id
  WHERE l.deck_id=s.deck_id AND lower(btrim(v.word))=lower(btrim(s.word))
  ORDER BY l.display_order, v.vocabulary_id LIMIT 1
) existing ON true;

SELECT DISTINCT ON (resolved_id) resolved_id,word,meaning,part_of_speech,example,'Original educational content'
FROM v26_resolved_words WHERE true ORDER BY resolved_id,display_order
ON CONFLICT (vocabulary_id) DO NOTHING;

SELECT deck_id,resolved_id,display_order FROM v26_resolved_words WHERE true
ON CONFLICT (deck_id,vocabulary_id) DO UPDATE SET display_order=EXCLUDED.display_order;

-- This migration intentionally does not populate IPA without pronunciation verification.
-- Validate 30 links per deck after Flyway applies V26.
